import os
import boto3

class AWSClient:
    def __init__(self):
        self.region_name = os.environ.get('AWS_REGION', 'us-east-1')
        self.user_pool_id = os.environ.get('AWS_COGNITO_USER_POOL_ID')
        self.client_id = os.environ.get('AWS_COGNITO_CLIENT_ID')

        if not self.user_pool_id or not self.client_id:
            raise ValueError("AWS_COGNITO_USER_POOL_ID and AWS_COGNITO_CLIENT_ID must be set as environment variables")

        self.cognito_client = boto3.client('cognito-idp', region_name=self.region_name)
        self.translate_client = boto3.client('translate', region_name=self.region_name)
        self.comprehend_client = boto3.client('comprehend', region_name=self.region_name)
        self.dynamodb_client = boto3.client('dynamodb', region_name=self.region_name)

    def get_cognito_client(self):
        return self.cognito_client

    def get_user_pool_id(self):
        return self.user_pool_id

    def get_client_id(self):
        return self.client_id

    def get_translate_client(self):
        return self.translate_client

    def get_comprehend_client(self):
        return self.comprehend_client

    def get_dynamodb_client(self):
        return self.dynamodb_client

from identity_client import AWSClient
from identity_models import RegisterUserRequest, RegisterUserResponse

def register_user(request: RegisterUserRequest) -> RegisterUserResponse:
    aws_client = AWSClient()
    cognito_client = aws_client.get_cognito_client()
    client_id = aws_client.get_client_id()

    try:
        response = cognito_client.sign_up(
            ClientId=client_id,
            Username=request.email,
            Password=request.password,
            UserAttributes=[
                {
                    'Name': 'email',
                    'Value': request.email
                },
            ]
        )
        return RegisterUserResponse(user_id=response['UserConfirmed'], message="User registration initiated. Please confirm your email.")
    except cognito_client.exceptions.UsernameExistsException:
        return RegisterUserResponse(user_id="", message="User with this email already exists.")
    except Exception as e:
        return RegisterUserResponse(user_id="", message=f"Registration failed: {str(e)}")

from identity_client import AWSClient
from identity_models import LoginRequest, LoginResponse

def email_password_login(request: LoginRequest) -> LoginResponse:
    aws_client = AWSClient()
    cognito_client = aws_client.get_cognito_client()
    client_id = aws_client.get_client_id()

    try:
        response = cognito_client.initiate_auth(
            ClientId=client_id,
            AuthFlow='USER_PASSWORD_AUTH',
            AuthParameters={
                'USERNAME': request.email,
                'PASSWORD': request.password
            }
        )
        auth_result = response['AuthenticationResult']
        return LoginResponse(
            access_token=auth_result['AccessToken'],
            refresh_token=auth_result['RefreshToken'],
            id_token=auth_result['IdToken'],
            expires_in=auth_result['ExpiresIn']
        )
    except cognito_client.exceptions.NotAuthorizedException:
        return LoginResponse(access_token="", refresh_token="", id_token="", expires_in=0)
    except Exception as e:
        return LoginResponse(access_token="", refresh_token="", id_token="", expires_in=0)

from identity_client import AWSClient
from identity_models import RefreshSessionRequest, RefreshSessionResponse

def refresh_session(request: RefreshSessionRequest) -> RefreshSessionResponse:
    aws_client = AWSClient()
    cognito_client = aws_client.get_cognito_client()
    client_id = aws_client.get_client_id()

    try:
        response = cognito_client.initiate_auth(
            ClientId=client_id,
            AuthFlow='REFRESH_TOKEN_AUTH',
            AuthParameters={
                'REFRESH_TOKEN': request.refresh_token
            }
        )
        auth_result = response['AuthenticationResult']
        return RefreshSessionResponse(
            access_token=auth_result['AccessToken'],
            id_token=auth_result['IdToken'],
            expires_in=auth_result['ExpiresIn']
        )
    except cognito_client.exceptions.NotAuthorizedException:
        return RefreshSessionResponse(access_token="", id_token="", expires_in=0)
    except Exception as e:
        return RefreshSessionResponse(access_token="", id_token="", expires_in=0)

from identity_client import AWSClient
from identity_models import PasswordResetRequest, PasswordResetResponse

def password_reset(request: PasswordResetRequest) -> PasswordResetResponse:
    aws_client = AWSClient()
    cognito_client = aws_client.get_cognito_client()
    client_id = aws_client.get_client_id()

    try:
        cognito_client.forgot_password(
            ClientId=client_id,
            Username=request.email
        )
        return PasswordResetResponse(message="Password reset initiated. Check your email for a verification code.")
    except cognito_client.exceptions.UserNotFoundException:
        return PasswordResetResponse(message="User not found.")
    except Exception as e:
        return PasswordResetResponse(message=f"Password reset failed: {str(e)}")

